mapper.select:
select w.*, p.project_name, p.required_skills, p.max_staff_count, s.sname as staff_name
from biz_workload_detail w
left join biz_task_project p on w.project_id = p.id
left join hr_employee s on w.staff_id = s.id
where 1=1

	and w.project_id = #{projectId}


	and w.work_date = #{workDate}


	and w.work_date >= #{startDate}


	and w.work_date <= #{endDate}


	and w.staff_id = #{staffId}

order by w.work_date desc, w.created_time desc

	limit #{startIndex}, #{pageSize}

SELECT 
	COUNT(*) as task_count,
	COALESCE(SUM(time_spent_hrs), 0) as total_hours,
	COALESCE(AVG(task_weight), 0) as avg_task_weight,
	COALESCE(AVG(quality_score), 0) as avg_quality,
	COALESCE(SUM(time_spent_hrs * task_weight * quality_score), 0) as eci_score
FROM biz_workload_detail
WHERE 1=1
AND staff_id = #{staffId}
AND project_id = #{projectId}
AND work_date >= #{startDate}
AND work_date <= #{endDate}

SELECT 
	DATE_FORMAT(work_date, '%Y-%m-%d') as date,
	SUM(time_spent_hrs) as hours
FROM biz_workload_detail
WHERE 1=1
AND staff_id = #{staffId}
AND project_id = #{projectId}
AND work_date >= #{startDate}
AND work_date <= #{endDate}
GROUP BY work_date
ORDER BY work_date

SELECT 
	DATE_FORMAT(work_date, '%Y年%m月') as month,
	SUM(time_spent_hrs) as hours,
	COUNT(*) as taskCount
FROM biz_workload_detail
WHERE 1=1
AND staff_id = #{staffId}
AND project_id = #{projectId}
AND work_date >= #{startDate}
AND work_date <= #{endDate}
GROUP BY DATE_FORMAT(work_date, '%Y-%m')
ORDER BY DATE_FORMAT(work_date, '%Y-%m')
